module TopModule (
    input  wire        clk,
    input  wire        in,
    input  wire        reset,
    output reg  [7:0]  out_byte,
    output reg         done
);

    // State encoding
    localparam IDLE = 2'd0,   // line idle, waiting for start bit (in == 0)
               DATA = 2'd1,   // receiving 8 data bits, LSB first
               STOP = 2'd2;   // expecting stop bit (in == 1)

    reg [1:0] state;
    reg [2:0] bitcnt;
    reg [7:0] data;

    always @(posedge clk) begin
        if (reset) begin
            state    <= IDLE;
            bitcnt   <= 3'd0;
            data     <= 8'd0;
            out_byte <= 8'd0;
            done     <= 1'b0;
        end else begin
            done <= 1'b0;   // default: done is a one-cycle pulse

            case (state)
                IDLE: begin
                    bitcnt <= 3'd0;
                    if (in == 1'b0)          // start bit detected
                        state <= DATA;
                end

                DATA: begin
                    data[bitcnt] <= in;      // LSB first
                    if (bitcnt == 3'd7) begin
                        bitcnt <= 3'd0;
                        state  <= STOP;
                    end else begin
                        bitcnt <= bitcnt + 3'd1;
                    end
                end

                STOP: begin
                    if (in == 1'b1) begin    // valid stop bit found
                        state    <= IDLE;
                        done     <= 1'b1;
                        out_byte <= data;
                    end
                    // If no stop bit, remain in STOP until one appears
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
```

**Explanation**

- **IDLE**: the line is high when idle; a low `in` marks a start bit, so the FSM moves to `DATA` and clears the bit counter.
- **DATA**: eight bits are shifted in LSB-first by writing `in` into `data[bitcnt]` and incrementing the counter; after the 8th bit it moves to `STOP`.
- **STOP**: if `in` is 1, the byte is correctly framed — `done` pulses for one cycle and `out_byte` is loaded with the received byte (both valid in the same cycle). If the stop bit is missing (`in == 0`), the FSM stays in `STOP` and keeps waiting until it "finds a stop bit", then asserts `done` again as required.
- **Reset**: active-high, synchronous, returning the FSM to IDLE with `done` deasserted.
